async (page) => { 
  const info = await page.evaluate(() => {
    return {
      title: document.title,
      url: location.href,
      links: Array.from(document.querySelectorAll('a')).map(a => ({text: a.textContent.trim(), href: a.href})),
      h1: document.querySelector('h1') ? document.querySelector('h1').textContent : 'none'
    };
  });
  return JSON.stringify(info);
}

async (page) => { 
  await page.goto('https://example.com');
  await page.waitForLoadState('load');
  const links = await page.$$eval('a', els => els.map(e => ({text: e.textContent.trim(), href: e.href})));
  const h1 = await page.$eval('h1', el => el.textContent).catch(() => 'no h1');
  const url = page.url();
  return { url, links, h1 };
}

async (page) => { 
  await page.goto('https://example.com');
  await page.waitForLoadState('load');
  const links = await page.$$eval('a', els => els.map(e => ({text: e.textContent.trim(), href: e.href})));
  const h1 = await page.$eval('h1', el => el.textContent).catch(() => 'no h1');
  const url = page.url();
  return { url, links, h1 };
}

async (page) => {
  const url = page.url();
  const title = await page.title();
  return `URL: ${url}, Title: ${title}`;
}

