CREATE TABLE customers (
    customer_id   INTEGER PRIMARY KEY,
    name          TEXT NOT NULL,
    email         TEXT
);

CREATE TABLE vip (
    customer_id  INTEGER PRIMARY KEY,
    total_amount REAL NOT NULL
);

SELECT c.name, v.customer_id, v.total_amount
FROM   vip v
JOIN   customers c ON c.customer_id = v.customer_id;
